1	/**
2	 * Mobile Wallet Gateway SDK Service
3	 * Handles mobile wallet transactions for Egyptian carriers:
4	 * - Vodafone Cash (vf_cash) -> *9*1# prompt
5	 * - Orange Cash (or_cash)   -> Under maintenance notice
6	 * - Etisalat Cash (et_cash) -> e& Money App prompt
7	 */
8	
9	export type Sha7nawyWalletMethod = "vf_cash" | "or_cash" | "et_cash";
10	
11	export interface CreatePaymentParams {
12	  number: string;
13	  amount: number;
14	  method: Sha7nawyWalletMethod;
15	  client?: string;
16	  details?: string;
17	  webhook_url?: string;
18	}
19	
20	export interface Sha7nawyPaymentData {
21	  id: number;
22	  amount: string;
23	  number: string;
24	  method: Sha7nawyWalletMethod;
25	  reference: string;
26	  status: string;
27	  client?: string;
28	  details?: string;
29	  transaction_id?: string;
30	  provider_transaction_id?: string;
31	  transaction_Time?: string;
32	  last_updated?: string;
33	  created_at?: string;
34	  updated_at?: string;
35	}
36	
37	export interface Sha7nawyCreateResponse {
38	  status: boolean;
39	  code: number;
40	  message: string;
41	  data?: Sha7nawyPaymentData;
42	  error?: string;
43	}
44	
45	export const WALLET_METHOD_LABELS: Record<Sha7nawyWalletMethod, string> = {
46	  vf_cash: "فودافون كاش",
47	  or_cash: "أورنج كاش (قيد الصيانة ⚠️)",
48	  et_cash: "اتصالات كاش (e& Money)",
49	};
50	
51	export const WALLET_INSTRUCTIONS: Record<Sha7nawyWalletMethod, string> = {
52	  vf_cash: "اطلب *9*1# خلال دقيقة واحدة واكتب الرقم السري لتأكيد عملية الخصم",
53	  or_cash: "محفظة أورنج كاش تحت الصيانة والتطوير حالياً — يرجى اختيار فودافون كاش أو اتصالات كاش لإتمام الدفع بسهولة.",
54	  et_cash: "افتَح تطبيق e& Money واقبل طلب الدفع المعلق فوراً",
55	};
56	
57	/**
58	 * Calculates 2% tax/fee on base payment amount
59	 */
60	export function calculateAmountWithTax(baseAmount: number): { baseAmount: number; taxAmount: number; totalAmount: number } {
61	  const taxAmount = Math.round(baseAmount * 0.02 * 100) / 100;
62	  const totalAmount = Math.round((baseAmount + taxAmount) * 100) / 100;
63	  return { baseAmount, taxAmount, totalAmount };
64	}
65	
66	/**
67	 * Validates an Egyptian mobile wallet phone number (11 digits starting with 01)
68	 */
69	export function validateEgyptianPhone(phone: string): boolean {
70	  const clean = phone.trim().replace(/\D/g, "");
71	  return /^01[0125]\d{8}$/.test(clean);
72	}
73	
74	/**
75	 * Normalizes phone number to 11 digits format (e.g. 01234567890)
76	 */
77	export function normalizeEgyptianPhone(phone: string): string {
78	  let clean = phone.trim().replace(/\D/g, "");
79	  if (clean.startsWith("20")) {
80	    clean = clean.slice(2);
81	  }
82	  if (clean.startsWith("+20")) {
83	    clean = clean.slice(3);
84	  }
85	  return clean;
86	}
