88	/**
89	 * Creates a mobile wallet payment request via Payment Gateway API
90	 */
91	export async function createSha7nawyPayment(
92	  params: CreatePaymentParams
93	): Promise<Sha7nawyCreateResponse> {
94	  const baseUrl = (process.env.SHA7NAWY_BASE_URL || "https://gate.sha7nawy.com").replace(/\/$/, "");
95	  const publicKey = process.env.SHA7NAWY_PUBLIC_KEY;
96	
97	  if (!publicKey) {
98	    throw new Error("SHA7NAWY_PUBLIC_KEY is not configured in environment");
99	  }
100	
101	  const cleanPhone = normalizeEgyptianPhone(params.number);
102	  if (!validateEgyptianPhone(cleanPhone)) {
103	    return {
104	      status: false,
105	      code: 400,
106	      message: "رقم المحفظة غير صحيح — يجب أن يكون رقم مصري مكون من 11 رقماً يبدأ بـ 01",
107	    };
108	  }
109	
110	  if (params.method === "or_cash") {
111	    return {
112	      status: false,
113	      code: 400,
114	      message: "محفظة أورنج كاش تحت الصيانة والتطوير حالياً لتقديم خدمة أفضل. يرجى اختيار فودافون كاش أو اتصالات كاش لإتمام عملية الدفع بسهولة دون قلق.",
115	    };
116	  }
117	
118	  if (!params.amount || params.amount < 5 || params.amount > 10000) {
119	    return {
120	      status: false,
121	      code: 400,
122	      message: "المبلغ غير مسموح به — الحد الأدنى 5 جنيه والحد الأقصى 10,000 جنيه",
123	    };
124	  }
125	
126	  const endpoint = `${baseUrl}/api/payment/create`;
127	
128	  try {
129	    const res = await fetch(endpoint, {
130	      method: "POST",
131	      headers: {
132	        "Accept": "application/json",
133	        "Content-Type": "application/json",
134	        "Authorization": publicKey,
135	      },
136	      body: JSON.stringify({
137	        number: cleanPhone,
138	        amount: params.amount,
139	        method: params.method,
140	        client: params.client || "codeup-user",
141	        details: params.details || "Code-UP Balance Top-up",
142	        webhook_url: params.webhook_url,
143	      }),
144	    });
145	
146	    const data = await res.json().catch(() => ({}));
147	
148	    if (!res.ok) {
149	      return {
150	        status: false,
151	        code: res.status,
152	        message: data.message || data.error || `تعذر الخصم من المحفظة حالياً (${res.status})`,
153	      };
154	    }
155	
156	    return {
157	      status: data.status ?? true,
158	      code: data.code ?? 200,
159	      message: data.message || WALLET_INSTRUCTIONS[params.method],
160	      data: data.data,
161	    };
162	  } catch (error: any) {
163	    console.error("[Gateway API] Error calling create payment:", error);
164	    return {
165	      status: false,
166	      code: 500,
167	      message: "تعذر الاتصال ببوابة الدفع الإلكتروني — حاول مرة أخرى لاحقاً",
168	    };
169	  }
170	}
