172	/**
173	 * Confirms a payment transaction using ref_code
174	 */
175	export async function confirmSha7nawyPayment(ref_code: string): Promise<Sha7nawyCreateResponse> {
176	  const baseUrl = (process.env.SHA7NAWY_BASE_URL || "https://gate.sha7nawy.com").replace(/\/$/, "");
177	  const publicKey = process.env.SHA7NAWY_PUBLIC_KEY;
178	
179	  if (!publicKey) {
180	    throw new Error("SHA7NAWY_PUBLIC_KEY is not configured");
181	  }
182	
183	  try {
184	    const res = await fetch(`${baseUrl}/api/payment/confirm`, {
185	      method: "POST",
186	      headers: {
187	        "Accept": "application/json",
188	        "Content-Type": "application/json",
189	        "Authorization": publicKey,
190	      },
191	      body: JSON.stringify({ ref_code }),
192	    });
193	
194	    const data = await res.json().catch(() => ({}));
195	    return {
196	      status: data.status ?? res.ok,
197	      code: data.code ?? res.status,
198	      message: data.message || (res.ok ? "تم التأكيد بنجاح" : "تعذر التأكيد"),
199	      data: data.data,
200	    };
201	  } catch (error: any) {
202	    console.error("[Gateway API] Error calling confirm payment:", error);
203	    return { status: false, code: 500, message: "تعذر الاتصال بسيرفر التأكيد" };
204	  }
205	}
