225	    });
226	
227	    const data = await res.json().catch(() => ({}));
228	    return {
229	      status: data.status ?? res.ok,
230	      code: data.code ?? res.status,
231	      message: data.message || "تم استعلام البيانات بنجاح",
232	      data: data.data,
233	    };
234	  } catch (error: any) {
235	    console.error("[Gateway API] Error querying payment info:", error);
236	    return { status: false, code: 500, message: "تعذر الاستعلام من سيرفر التأكيد" };
237	  }
238	}

