1	import { NextRequest, NextResponse } from "next/server";
2	import { prisma } from "@/lib/prisma";
3	import { getSha7nawyPaymentInfo } from "@/lib/sha7nawy";
4	
5	export async function POST(req: NextRequest) {
6	  try {
7	    const payload = await req.json().catch(() => ({}));
8	    console.log("[Sha7nawy Webhook] Body:", JSON.stringify(payload));
9	
10	    const event = payload.event || req.headers.get("x-webhook-event");
11	    const transaction = payload.transaction || payload.data || {};
12	
13	    const status = transaction.status || req.headers.get("x-transaction-status") || payload.status;
14	    const reference = transaction.reference || req.headers.get("x-transaction-reference") || transaction.id;
15	    const clientUserId = transaction.client || payload.client;
16	    const rawAmount = transaction.amount || payload.amount;
17	    const transactionId = transaction.id || req.headers.get("x-transaction-id");
18	
19	    if (event !== "transaction.updated" && !status) {
20	      return NextResponse.json({ success: true, message: "Ignored non-transaction event" }, { status: 200 });
21	    }
22	
23	    if (status === "rejected") {
24	      console.log(`[Sha7nawy Webhook] Transaction ${reference} was rejected/failed.`);
25	      return NextResponse.json({ success: true, processed: false, reason: "Transaction rejected" }, { status: 200 });
26	    }
27	
28	    const isCompleted = status === "completed" || status === "success" || status === "paid";
29	    if (!isCompleted) {
30	      return NextResponse.json({ success: true, processed: false, reason: `Status is ${status}` }, { status: 200 });
31	    }
32	
33	    // Optional Security Best Practice: Verify directly with Sha7nawy Server via Secret Key if transactionId is present
34	    if (transactionId && process.env.SHA7NAWY_SECRET_KEY) {
35	      const verifyRes = await getSha7nawyPaymentInfo(transactionId);
36	      if (verifyRes.status && verifyRes.data) {
37	        if (verifyRes.data.status !== "completed") {
38	          console.warn(`[Sha7nawy Webhook] Security verification failed: Server status is ${verifyRes.data.status}`);
39	          return NextResponse.json({ error: "Verification status mismatch" }, { status: 400 });
40	        }
41	      }
42	    }
43	
44	    const amount = typeof rawAmount === "string" ? parseFloat(rawAmount) : Number(rawAmount);
45	
46	    if (!clientUserId || !amount || isNaN(amount) || amount <= 0) {
47	      console.warn("[Sha7nawy Webhook] Missing client or amount in payload:", { clientUserId, amount });
48	      return NextResponse.json({ error: "Invalid payload parameters" }, { status: 400 });
49	    }
50	
51	    // Find student in DB
52	    const user = await prisma.user.findUnique({
53	      where: { id: clientUserId },
54	      select: { id: true, balance: true },
55	    });
56	
57	    if (!user) {
58	      console.error(`[Sha7nawy Webhook] User ID ${clientUserId} not found.`);
59	      return NextResponse.json({ error: "User not found" }, { status: 404 });
60	    }
61	
62	    // Check Idempotency: Prevent duplicate credits for the same reference
63	    const noteSearch = `مرجع: ${reference}`;
64	    const existingTx = await prisma.balanceTransaction.findFirst({
65	      where: {
66	        userId: user.id,
67	        note: { contains: reference ? String(reference) : "sha7nawy" },
68	      },
69	    });
70	
71	    if (existingTx) {
72	      console.log(`[Sha7nawy Webhook] Reference ${reference} already credited.`);
73	      return NextResponse.json({ success: true, processed: false, reason: "Already credited" }, { status: 200 });
74	    }
75	
76	    // Atomically credit user balance and log ledger entry
77	    await prisma.$transaction(async (tx) => {
78	      await tx.user.update({
79	        where: { id: user.id },
80	        data: { balance: { increment: amount } },
81	      });
82	
83	      await tx.balanceTransaction.create({
84	        data: {
85	          userId: user.id,
86	          type: "credit_sha7nawy_wallet",
87	          amount: amount,
88	          note: `شحن محفظة عبر Sha7nawy (مرجع: ${reference || "N/A"})`,
89	        },
90	      });
91	    });
92	
93	    console.log(`[Sha7nawy Webhook] Successfully credited ${amount} EGP to student ${user.id}`);
94	    return NextResponse.json({ success: true, credited: amount, reference }, { status: 200 });
95	  } catch (error: any) {
96	    console.error("[Sha7nawy Webhook] Error:", error);
97	    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
98	  }
99	}

