12	  if (!session) return NextResponse.json({ error: "يجب تسجيل الدخول أولاً" }, { status: 401 });
13	  if (session.role === "teacher" || session.role === "staff") {
14	    return NextResponse.json({ error: "هذا الإجراء مخصص للمتعلمين فقط" }, { status: 403 });
15	  }
16	
17	  const { id: courseId } = await params;
18	  const reqBody = await req.json().catch(() => ({}));
19	  const promoCodeInput = reqBody.promoCode || reqBody.promo_code;
20	
21	  const course = await prisma.course.findUnique({
22	    where: { id: courseId },
23	    select: { id: true, title: true, teacherId: true, isPaid: true, price: true, discountPercent: true, discountExpiresAt: true },
24	  });
25	  if (!course) return NextResponse.json({ error: "الكورس غير موجود" }, { status: 404 });
26	
27	  // Calculate effective price
28	  const now = new Date();
29	  const discountActive =
30	    course.discountPercent != null &&
31	    course.discountPercent > 0 &&
32	    (course.discountExpiresAt == null || course.discountExpiresAt > now);
33	
34	  const effectivePrice = (() => {
35	    if (!course.isPaid || !course.price) return 0;
36	    if (discountActive && course.discountPercent) {
37	      return +(course.price * (1 - course.discountPercent / 100)).toFixed(2);
38	    }
39	    return course.price;
40	  })();
41	
42	  if (effectivePrice === 0) {
43	    return NextResponse.json({ error: "هذا الكورس مجاني — استخدم زر التسجيل المباشر" }, { status: 400 });
44	  }
45	
46	  const code = `PAY-${Date.now().toString(36).toUpperCase()}-${randomBytes(3).toString("hex").toUpperCase()}`;
47	
48	  try {
49	    const purchaseResult = await prisma.$transaction(async (tx) => {
50	      // 1. Acquire advisory lock on student wallet
51	      await acquireAdvisoryLock(`purchase-course-${session.id}`, tx);
52	
53	      // 2. Check already enrolled inside the transaction
54	      const existing = await tx.accessCode.findFirst({
55	        where: { courseId, studentId: session.id },
56	        select: { id: true },
57	      });
58	      if (existing) throw new Error("ALREADY_ENROLLED");
59	
60	      // 3. Check balance inside the transaction
61	      const student = await tx.user.findUnique({
62	        where: { id: session.id },
63	        select: { balance: true },
64	      });
65	      if (!student) throw new Error("USER_NOT_FOUND");
66	
67	      const currentBalance = student.balance ?? 0;
68	      if (currentBalance < effectivePrice) throw new Error("INSUFFICIENT_FUNDS");
69	
70	      // 4. Update balance atomically using decrement
71	      await tx.user.update({
72	        where: { id: session.id },
73	        data: { balance: { decrement: effectivePrice } },
74	      });
75	
76	      // 5. Create AccessCode
77	      await tx.accessCode.create({
78	        data: { code, courseId, studentId: session.id, isActive: true, usedAt: now },
79	      });
80	
81	      // 6. Create BalanceTransaction
82	      await tx.balanceTransaction.create({
83	        data: {
84	          userId: session.id,
85	          type: "debit_course",
86	          amount: -effectivePrice,
87	          note: `شراء كورس: ${course.title}`,
88	        },
89	      });
90	
91	      // 7. Process Teacher Referral Attribution
92	      await processTeacherAttribution({
93	        studentId: session.id,
94	        teacherIdOfContent: course.teacherId,
95	        amount: effectivePrice,
96	        purchaseType: "COURSE",
97	        courseId: course.id,
98	        promoCodeInput,
99	        tx,
100	      });
101	
102	      return {
103	        newBalance: +(currentBalance - effectivePrice).toFixed(2),
104	      };
105	    });
106	
107	    return NextResponse.json({
108	      success: true,
109	      courseId,
110	      courseTitle: course.title,
111	      charged: effectivePrice,
112	      newBalance: purchaseResult.newBalance,
113	      message: `تم شراء «${course.title}» بنجاح! خُصم ${effectivePrice} جنيه — رصيدك الآن ${purchaseResult.newBalance} جنيه.`,
114	    });
115	  } catch (err: any) {
116	    if (err.message === "ALREADY_ENROLLED") {
117	      return NextResponse.json({ error: "أنت مسجّل بالفعل في هذا الكورس" }, { status: 400 });
118	    }
119	    if (err.message === "USER_NOT_FOUND") {
120	      return NextResponse.json({ error: "المستخدم غير موجود" }, { status: 404 });
121	    }
122	    if (err.message === "INSUFFICIENT_FUNDS") {
123	      return NextResponse.json({ error: "رصيدك غير كافٍ لإتمام العملية" }, { status: 400 });
124	    }
125	    throw err;
126	  }
127	}

