27	/** POST — redeem a money code */
28	export async function POST(req: NextRequest) {
29	  const { getSession } = await import("@/lib/auth");
30	  const session = await getSession();
31	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
32	
33	  const { code } = await req.json() as { code?: string };
34	  if (!code?.trim()) return NextResponse.json({ error: "الكود مطلوب" }, { status: 400 });
35	
36	  const normalized = code.trim().toUpperCase();
37	
38	  try {
39	    const creditedAmount = await prisma.$transaction(async (tx) => {
40	      const moneyCode = await tx.moneyCode.findUnique({ where: { code: normalized } });
41	      if (!moneyCode) {
42	        throw new Error("NOT_FOUND");
43	      }
44	      if (moneyCode.isUsed) {
45	        throw new Error("ALREADY_USED");
46	      }
47	      if (moneyCode.expiresAt && moneyCode.expiresAt < new Date()) {
48	        throw new Error("EXPIRED");
49	      }
50	
51	      // Mark used conditionally - ensures that if another request updated it between findUnique and now, this updates 0 rows
52	      const updateResult = await tx.moneyCode.updateMany({
53	        where: { id: moneyCode.id, isUsed: false },
54	        data: { isUsed: true, usedById: session.id, usedAt: new Date() },
55	      });
56	
57	      if (updateResult.count === 0) {
58	        throw new Error("ALREADY_USED");
59	      }
60	
61	      // Atomically increment user's balance
62	      await tx.user.update({
63	        where: { id: session.id },
64	        data: { balance: { increment: moneyCode.amount } },
65	      });
66	
67	      // Create ledger entry
68	      await tx.balanceTransaction.create({
69	        data: {
70	          userId: session.id,
71	          type: "credit_code",
72	          amount: moneyCode.amount,
73	          note: `كود: ${normalized}`,
74	        },
75	      });
76	
77	      return moneyCode.amount;
78	    });
79	
80	    return NextResponse.json({
81	      success: true,
82	      credited: creditedAmount,
83	      message: `تم إضافة ${creditedAmount} جنيه إلى رصيدك!`,
84	    });
85	  } catch (error: any) {
86	    if (error.message === "NOT_FOUND") {
87	      return NextResponse.json({ error: "الكود غير صحيح" }, { status: 404 });
88	    }
89	    if (error.message === "ALREADY_USED") {
90	      return NextResponse.json({ error: "هذا الكود مستخدم بالفعل" }, { status: 400 });
91	    }
92	    if (error.message === "EXPIRED") {
93	      return NextResponse.json({ error: "الكود منتهي الصلاحية" }, { status: 400 });
94	    }
95	    console.error("[balance redemption] error:", error);
96	    return NextResponse.json({ error: "حدث خطأ داخلي" }, { status: 500 });
97	  }
98	}

