31	  } = input;
32	
33	  if (amount <= 0 || !teacherIdOfContent) return;
34	
35	  const now = new Date();
36	  const PROMO_EXPIRY_MS = 350 * 24 * 60 * 60 * 1000;
37	
38	  // Case A: Explicit promo code entered at purchase time
39	  if (promoCodeInput) {
40	    const codeUpper = String(promoCodeInput).trim().toUpperCase();
41	    const promoTeacher = await db.user.findFirst({
