43	        role: "teacher",
44	        promoProgramEnabled: true,
45	        promoCode: codeUpper,
46	      },
47	      select: { id: true, promoCodeCreatedAt: true },
48	    });
49	
50	    if (promoTeacher && promoTeacher.id === teacherIdOfContent && promoTeacher.promoCodeCreatedAt) {
