107	export async function setPhoneVerificationCookie(token: string) {
108	  const cookieStore = await cookies();
109	  const isSecure = process.env.NODE_ENV === "production" && process.env.SECURE_COOKIES === "true";
110	  cookieStore.set(PHONE_VERIFY_COOKIE_NAME, token, {
111	    httpOnly: true,
112	    secure: isSecure,
113	    sameSite: "strict",
114	    maxAge: 60 * 3,
115	    path: "/",
116	  });
117	}
