124	export async function verifyPhoneVerificationCookie(phone: string, code: string) {
125	  const cookieStore = await cookies();
126	  const token = cookieStore.get(PHONE_VERIFY_COOKIE_NAME)?.value;
127	
128	  if (!token) {
129	    return false;
130	  }
131	
132	  try {
133	    const { payload } = await jwtVerify(token, JWT_SECRET);
134	    const challenge = payload as unknown as PhoneChallengePayload;
135	    if (!challenge?.phone) return false;
136	    const normalizedPhone = normalizeEgyptPhone(String(phone));
137	    if (challenge.phone !== normalizedPhone) return false;
138	
139	    if (isPhoneVerificationBypassed()) {
140	      return true;
141	    }
142	
143	    if (!challenge.codeHash) return false;
144	    const codeHash = hashVerificationCode(code.trim());
145	    return challenge.codeHash === codeHash;
146	  } catch {
147	    return false;
148	  }
149	}
