244	export async function getSessionWithRetry(
245	  maxRetries = 3,
246	  delayMs = 100,
247	  options?: SessionOptions
248	): Promise<SessionUser | null> {
249	  for (let attempt = 0; attempt < maxRetries; attempt++) {
250	    const session = await getSession(options);
251	    if (session) {
252	      return session;
253	    }
254	    if (attempt < maxRetries - 1) {
255	      await new Promise((resolve) => setTimeout(resolve, delayMs * (attempt + 1)));
256	    }
257	  }
258	  return null;
259	}
