1	import crypto from "crypto";
2	import { prisma } from "@/lib/prisma";
3	
4	export class AccessCodeGuard {
5	  private static SERVER_SECRET = process.env.ACCESS_CODE_SECRET || "codeup_access_code_server_secret_2026";
6	
7	  /**
8	   * Generates a cryptographically secure, high-entropy access code.
9	   * Example output: "P9X7-WK4M-QT2H"
10	   */
11	  public static generateSecureCode(): string {
12	    const charset = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
13	    const getRandomChar = () => charset[crypto.randomInt(0, charset.length)];
14	
15	    const part1 = Array.from({ length: 4 }, getRandomChar).join("");
16	    const part2 = Array.from({ length: 4 }, getRandomChar).join("");
17	    const part3 = Array.from({ length: 4 }, getRandomChar).join("");
18	
19	    return `${part1}-${part2}-${part3}`;
20	  }
21	
22	  /**
23	   * Computes SHA-256 HMAC hash of code using server secret for secure storage at rest.
24	   */
25	  public static hashCode(code: string): string {
26	    const normalized = String(code).trim().toUpperCase();
27	    return crypto
28	      .createHmac("sha256", this.SERVER_SECRET)
29	      .update(normalized)
30	      .digest("hex");
31	  }
32	
33	  /**
34	   * Performs constant-time comparison of two string hashes to prevent timing attacks.
35	   */
36	  public static constantTimeCompare(hashA: string, hashB: string): boolean {
37	    const bufA = Buffer.from(hashA, "utf-8");
38	    const bufB = Buffer.from(hashB, "utf-8");
39	
40	    if (bufA.length !== bufB.length) return false;
41	    return crypto.timingSafeEqual(bufA, bufB);
42	  }
43	
44	  /**
45	   * Exponential rate-limit check per IP and User ID.
46	   * Lockout thresholds:
47	   *   - 5 failures in last 10 mins  => 30-second lock
48	   *   - 10 failures in last 30 mins => 5-minute lock
49	   *   - 20 failures in last 1 hour  => 1-hour lock
50	   */
51	  public static async verifyRateLimit(
52	    ip: string,
53	    userId?: string
54	  ): Promise<{ allowed: boolean; lockTimeSeconds: number; failureCount: number }> {
55	    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
56	
57	    const failures = await prisma.accessCodeLog.count({
58	      where: {
59	        OR: [{ ip }, ...(userId ? [{ userId }] : [])],
60	        success: false,
61	        createdAt: { gte: oneHourAgo },
62	      },
63	    });
64	
65	    if (failures >= 20) {
66	      return { allowed: false, lockTimeSeconds: 3600, failureCount: failures };
67	    }
68	    if (failures >= 10) {
69	      return { allowed: false, lockTimeSeconds: 300, failureCount: failures };
70	    }
71	    if (failures >= 5) {
72	      return { allowed: false, lockTimeSeconds: 30, failureCount: failures };
73	    }
74	
75	    return { allowed: true, lockTimeSeconds: 0, failureCount: failures };
76	  }
77	
78	  /**
79	   * Logs access code redemption attempt for audit telemetry.
80	   * NEVER stores raw code input.
81	   */
82	  public static async logAttempt(params: {
83	    ip: string;
84	    userId?: string;
85	    codeAttempted: string;
86	    success: boolean;
87	  }): Promise<void> {
88	    const rawInput = String(params.codeAttempted || "").trim().toUpperCase();
89	    const attemptHash = this.hashCode(rawInput);
90	    const first4Characters = rawInput.substring(0, 4);
91	    const codeLength = rawInput.length;
92	
93	    await prisma.accessCodeLog.create({
94	      data: {
95	        ip: params.ip,
96	        userId: params.userId,
97	        attemptHash,
98	        first4Characters,
99	        codeLength,
100	        success: params.success,
101	      },
102	    }).catch(() => {});
103	
104	    // Audit Log for security monitoring
105	    await prisma.auditLog.create({
106	      data: {
107	        userId: params.userId,
108	        action: params.success ? "ACCESS_CODE_REDEEMED" : "ACCESS_CODE_FAILED",
109	        ip: params.ip,
110	        metadata: JSON.stringify({
111	          first4: first4Characters,
112	          length: codeLength,
113	          success: params.success,
114	        }),
115	      },
116	    }).catch(() => {});
117	  }
118	}

1	import { prisma } from "@/lib/prisma";
2	import { POINTS } from "@/lib/points";
3	
4	export type ReferralStatus = "PENDING" | "QUALIFIED" | "REWARDED" | "INVALID";
5	
6	export class ReferralService {
7	  /**
8	   * Registers a new PENDING referral link when student B signs up using Student A's referral code.
9	   * Does NOT award any points on raw signup to prevent bot farming.
10	   */
11	  public static async registerPendingReferral(
12	    inviterId: string,
13	    invitedId: string
14	  ): Promise<boolean> {
15	    if (inviterId === invitedId) {
16	      console.warn(`[ReferralService] Rejected self-referral for user ${inviterId}`);
17	      return false;
18	    }
19	
20	    try {
21	      await prisma.referral.create({
22	        data: {
23	          inviterId,
24	          invitedId,
25	          status: "PENDING",
26	        },
27	      });
28	      return true;
29	    } catch (err) {
30	      // Handles UNIQUE(invitedId) constraint if user was already referred
31	      console.warn(`[ReferralService] User ${invitedId} already has a referral record.`);
32	      return false;
33	    }
34	  }
35	
36	  /**
37	   * Qualifies and awards referral rewards (POINTS.REFERRAL to inviter & invited student)
38	   * upon a valid paid course purchase or access code redemption.
39	   * 
40	   * Atomically transitions status PENDING -> QUALIFIED -> REWARDED inside a transaction.
41	   */
42	  public static async qualifyAndRewardReferral(
43	    invitedStudentId: string,
44	    qualifyingPurchaseId: string
45	  ): Promise<{ rewarded: boolean; pointsAwarded: number }> {
46	    return await prisma.$transaction(async (tx) => {
47	      const referral = await tx.referral.findUnique({
48	        where: { invitedId: invitedStudentId },
49	      });
50	
51	      if (!referral) {
52	        return { rewarded: false, pointsAwarded: 0 };
53	      }
54	
55	      // Must be in PENDING status and not previously rewarded
56	      if (referral.status !== "PENDING") {
57	        return { rewarded: false, pointsAwarded: 0 };
58	      }
59	
60	      // Transition to REWARDED state atomically
61	      await tx.referral.update({
62	        where: { id: referral.id },
63	        data: {
64	          status: "REWARDED",
65	          qualifyingPurchaseId,
66	          rewardedAt: new Date(),
67	        },
68	      });
69	
70	      // Award POINTS.REFERRAL (+50 XP) to inviter & invited student
71	      const rewardPoints = POINTS.REFERRAL ?? 50;
72	      await tx.user.update({
73	        where: { id: referral.inviterId },
74	        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
75	      });
76	
77	      await tx.user.update({
78	        where: { id: referral.invitedId },
79	        data: { points: { increment: rewardPoints }, pointsUpdatedAt: new Date() },
80	      });
81	
82	      // Audit Log
83	      await tx.auditLog.create({
84	        data: {
85	          userId: referral.invitedId,
86	          action: "REFERRAL_REWARDED",
87	          ip: "127.0.0.1",
88	          metadata: JSON.stringify({
89	            inviterId: referral.inviterId,
90	            invitedId: referral.invitedId,
91	            qualifyingPurchaseId,
92	            rewardPoints,
93	          }),
94	        },
95	      }).catch(() => {});
96	
97	      console.log(`[ReferralService] Successfully rewarded ${rewardPoints} XP to inviter ${referral.inviterId} and invited ${referral.invitedId}`);
98	
99	      return { rewarded: true, pointsAwarded: rewardPoints };
100	    });
101	  }
102	
103	  /**
104	   * Retrieves summary telemetry of referrals for admin security dashboard.
105	   */
106	  public static async getReferralTelemetry(): Promise<{
107	    pending: number;
108	    qualified: number;
109	    rewarded: number;
110	    invalid: number;
111	    total: number;
112	  }> {
113	    const [pending, qualified, rewarded, invalid, total] = await Promise.all([
114	      prisma.referral.count({ where: { status: "PENDING" } }),
115	      prisma.referral.count({ where: { status: "QUALIFIED" } }),
116	      prisma.referral.count({ where: { status: "REWARDED" } }),
117	      prisma.referral.count({ where: { status: "INVALID" } }),
118	      prisma.referral.count(),
119	    ]);
120	
121	    return { pending, qualified, rewarded, invalid, total };
122	  }
123	}

