26	  const { id: studentId } = await params;
27	  const { amount, note } = await req.json() as { amount: number; note?: string };
28	
29	  if (!amount || amount === 0) return NextResponse.json({ error: "المبلغ مطلوب" }, { status: 400 });
30	
31	  const student = await prisma.user.findUnique({
32	    where: { id: studentId, role: "student", isDeleted: false },
