35	  if (!student) return NextResponse.json({ error: "الطالب غير موجود" }, { status: 404 });
36	
37	  const currentBalance = student.balance ?? 0;
38	  if (amount < 0 && currentBalance + amount < 0) {
39	    return NextResponse.json({ error: "الرصيد غير كافٍ للخصم" }, { status: 400 });
