50	      data: {
51	        userId:  studentId,
52	        type:    amount > 0 ? "credit_admin" : "debit_admin",
53	        amount,
54	        note:    note ?? (amount > 0 ? "إضافة رصيد من الإدارة" : "خصم رصيد من الإدارة"),
55	        adminId: session.id,
56	      },
57	    }),
58	  ]);
59	
60	  const updated = await prisma.user.findUnique({ where: { id: studentId }, select: { balance: true } });
61	
62	  return NextResponse.json({
63	    success: true,
64	    newBalance: updated?.balance ?? 0,
65	    message: `${amount > 0 ? "تم إضافة" : "تم خصم"} ${Math.abs(amount)} جنيه ${amount > 0 ? "إلى" : "من"} رصيد ${student.name} — الرصيد الآن ${newBalance} جنيه`,
