6	function generateCode(prefix = "CODEUP"): string {
7	  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
8	  const random = Array.from({ length: 8 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
9	  return `${prefix}-${random}`;
10	}
