16	
17	  const codes = await prisma.moneyCode.findMany({
18	    orderBy: { createdAt: "desc" },
19	    take: 100,
20	    select: { id: true, code: true, amount: true, isUsed: true, usedById: true, usedAt: true, expiresAt: true, createdAt: true },
21	  });
