26	/** POST — generate money codes (superadmin only) */
27	export async function POST(req: NextRequest) {
28	  const session = await getSession();
29	
30	    if (session && session.role === "superadmin") {
31	      try {
32	        await logAdminAction({
33	          adminId: session.id,
34	          adminName: session.name,
35	          action: "SUPERADMIN_ACTION",
36	          targetType: "API_ROUTE",
37	          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
38	          targetName: req.method,
39	        });
40	      } catch (e) {}
41	    }
42	  if (!session || session.role !== "superadmin") return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
43	
44	  const body = await req.json() as { amount: number; count?: number; expiresAt?: string; prefix?: string };
45	  const { amount, count = 1, expiresAt, prefix = "CODEUP" } = body;
46	
47	  if (!amount || amount <= 0) return NextResponse.json({ error: "المبلغ يجب أن يكون أكبر من صفر" }, { status: 400 });
48	  if (count < 1 || count > 100) return NextResponse.json({ error: "العدد يجب بين 1 و 100" }, { status: 400 });
49	
50	  const codes: string[] = [];
51	  for (let i = 0; i < count; i++) {
52	    let code: string;
53	    // Ensure uniqueness
54	    do { code = generateCode(prefix); } while (await prisma.moneyCode.findUnique({ where: { code }, select: { id: true } }));
55	    codes.push(code);
56	  }
57	
58	  const created = await prisma.moneyCode.createMany({
59	    data: codes.map(code => ({
60	      code,
61	      amount,
62	      expiresAt: expiresAt ? new Date(expiresAt) : null,
63	    })),
64	  });
65	
66	  return NextResponse.json({ success: true, count: created.count, codes });
